//go:embed migrations/*.sql
var migrationsFS embed.FS

func runMigrations(dbURL string) error {
	src, err := iofs.New(migrationsFS, "migrations") // read embedded files
	if err != nil {
		return err
	}
	m, err := migrate.NewWithSourceInstance("iofs", src, dbURL)
	if err != nil {
		return err
	}
	defer m.Close()
	// ErrNoChange just means already up to date, not a real failure.
	if err := m.Up(); err != nil && !errors.Is(err, migrate.ErrNoChange) {
		return err
	}
	return nil
}
